 const pname=(P,k)=>((P.depts||[]).find(d=>d.portal_name===k)||{name:k}).name;
 function reveal(j){const I=j.insights,P=j.payroll;if(!I&&j.tier){const tz=(id,title,lines,what)=>'<details class="gv-branch" id="gv-'+id+'"><summary>'+X(title)+' <span class="gv-mo">Members</span></summary><ul class="gv-people gv-key">'+lines.map(l=>'<li><b>'+X(l)+'</b></li>').join('')+'</ul>'+lockBox(what)+'</details>';return tz('reveal','What the numbers reveal',['How fast management grew compared with the workforce since 2011.','Who takes most of the overtime.','Whether hiring would cost less than overtime at the biggest agencies.','Which agencies are losing people fastest, and where the retirement wave hits.','Jobs the budget pays for versus people actually paid.'],'Findings from following 50,000 people through 16 years of state payroll, matched to the budget.')}if(!I||!P)return '';const ys=Object.keys(I.managers_by_year).sort(),a=I.managers_by_year[ys[0]],b=I.managers_by_year[ys[ys.length-1]];
  const pc=(x,y)=>((y-x)/x*100).toFixed(1)+'%';const H=I.ot_vs_hire||[];const E=Object.entries(I.departments);
  const turn=E.filter(([k,v])=>v.turnover&&v.turnover.length).map(([k,v])=>[pname(P,k),v.turnover[v.turnover.length-1][1],v.turnover[0][1]]).sort((x,y)=>y[1]-x[1]).slice(0,12);
  const ret=E.filter(([k,v])=>v.since_first_year_pct!=null).map(([k,v])=>[pname(P,k),v.since_first_year_pct,v.since_first_year]).sort((x,y)=>y[1]-x[1]).slice(0,12);
  const fill=E.filter(([k,v])=>v.fte_cap).map(([k,v])=>[pname(P,k),v.fte_cap,v.on_payroll_now]).sort((x,y)=>(y[1]-y[2])-(x[1]-x[2]));
  const li=(t,b)=>'<li><b>'+t+'</b> '+b+'</li>';
  const node=(title,sub,body)=>'<details class="gv-node"><summary><b>'+X(title)+'</b>'+(sub?'<span>'+X(sub)+'</span>':'')+'</summary><div class="gv-nb">'+body+'</div></details>';
  return '<details class="gv-branch" id="gv-reveal"><summary>What the numbers reveal</summary><p class="gv-sub">Findings no agency publishes. We followed '+I.people_tracked.toLocaleString()+' people through '+ys.length+' years of state payroll records and matched them against the budget. ('+I.ambiguous_names_dropped+' names shared by two people in the same year were left out.)</p>'+
   '<ul class="gv-people gv-key">'+
   li('Managers grew '+pc(a[1],b[1])+' while the workforce grew '+pc(a[0],b[0])+'.','Job titles with chief, director, deputy, administrator, manager, supervisor or superintendent went from '+a[1].toLocaleString()+' in '+ys[0]+' to '+b[1].toLocaleString()+' in '+ys[ys.length-1]+', not counting seasonal staff.')+
   li('The top 10% of overtime earners take '+I.ot_top10_share+'% of all overtime.','Of '+I.ot_earners.toLocaleString()+' people paid overtime in '+I.full_year+'.')+
   (H[0]?li(X(H[0][1])+'s at '+X(pname(P,H[0][0]))+' earned '+$M(H[0][2])+' in overtime.','That is about the cost of '+H[0][4]+' more full-time '+X(H[0][1].toLowerCase())+'s with benefits (median pay '+$M(H[0][3])+', times '+I.load+' for benefits). Per hour, time-and-a-half overtime costs about the same as a new hire with benefits, so hiring would mainly spread the hours rather than save money.'):'')+
   li('People who stayed in the same job got a median '+I.state_raise_same_title+'% raise from '+I.raise_window.join(' to ')+'.','Changing titles paid far more; each agency’s figure is in its Workforce drop-down.')+'</ul>'+
   '<div class="gv-band"><div class="gv-cards">'+
   node('Overtime versus hiring','Biggest overtime job titles','<table class="gv-tbl"><tr><th>Title</th><th>Overtime</th><th>Median pay</th><th>Equal to hires</th></tr>'+H.map(h=>'<tr><td>'+X(h[1])+'<br><small>'+X(pname(P,h[0]))+'</small></td><td>'+$M(h[2])+'</td><td>'+$M(h[3])+'</td><td>'+h[4]+'</td></tr>').join('')+'</table>')+
   node('Who is losing people','Share of year-round staff who left, latest year','<table class="gv-tbl"><tr><th>Agency</th><th>Latest</th><th>3 years earlier</th></tr>'+turn.map(r=>'<tr><td>'+X(r[0])+'</td><td>'+r[1]+'%</td><td>'+r[2]+'%</td></tr>').join('')+'</table>')+
   node('The retirement wave','Share of current staff on the payroll since '+I.first_year,'<table class="gv-tbl"><tr><th>Agency</th><th>Share</th><th>People</th></tr>'+ret.map(r=>'<tr><td>'+X(r[0])+'</td><td>'+r[1]+'%</td><td>'+r[2].toLocaleString()+'</td></tr>').join('')+'</table>')+
   node('Funded jobs versus people paid','Budget job cap vs. year-round people on the payroll now','<table class="gv-tbl"><tr><th>Agency</th><th>Budgeted</th><th>Paid now</th></tr>'+fill.map(r=>'<tr><td>'+X(r[0])+'</td><td>'+(+r[1]).toLocaleString()+'</td><td>'+r[2].toLocaleString()+'</td></tr>').join('')+'</table><p class="gv-sub">A gap can mean open positions the budget pays for, or staff counted elsewhere. Part-time staff count as one person each.</p>')+
   '</div></div></details>'}
 /* ---------- Where to cut: our assessment (opinion, built on the numbers above) ---------- */
 window.gvAssess=function(j){const A=j.assessment;if(!A||!(A.items||[]).length)return '';const FR=!A.items[0].why;
  const tag={cut:['Cut candidate','#B5123A'],trim:['Trim and restructure','#8A5A00'],fix:['Fix overtime, not headcount','#0F4C9A'],hold:['Hold','#2F6B4F']};
  return '<details class="gv-branch" id="gv-assess"><summary>Where to cut: our assessment</summary><p class="gv-sub"><b>Opinion.</b> '+X(A.intro||'')+'</p>'+(A.method?'<details class="gv-sd"><summary>How we judged</summary><div class="gv-nb"><ul class="gv-people">'+A.method.map(m=>'<li>'+X(m)+'</li>').join('')+'</ul></div></details>':'')+
   '<div class="gv-band"><div class="gv-cards">'+A.items.map(it=>{const g=tag[it.call]||['Review','#46566A'];
    return '<details class="gv-node" data-q="'+X((it.agency+' '+(it.why||[]).join(' ')).toLowerCase())+'"><summary><b>'+X(it.agency)+'</b><i style="color:#fff;background:'+g[1]+';padding:3px 8px;border-radius:3px">'+X(g[0])+'</i>'+(it.savings?'<span>Possible savings: '+X(it.savings)+'</span>':'')+'</summary><div class="gv-nb">'+
     (it.numbers?'<span class="gv-facts">'+it.numbers.map(n=>'<span class="gv-fact"><em>'+X(n[0])+'</em> '+X(n[1])+'</span>').join('')+'</span>':'')+
     (FR?lockBox('The numbers, our reasoning, the strongest argument against it and what to check next.'):'<p><b>Why:</b></p><ul class="gv-people">'+(it.why||[]).map(w=>'<li>'+X(w)+'</li>').join('')+'</ul>')+(it.counter?'<p><b>The other side:</b> '+X(it.counter)+'</p>':'')+(it.next?'<p><b>What to check next:</b> '+X(it.next)+'</p>':'')+'</div></details>'}).join('')+'</div></div>'+
   (A.caveats?'<p class="gv-indep">'+X(A.caveats)+'</p>':'')+'</details>'};

 /* ---------- CCRI ---------- */
 window.vCcri=function(){load('ccri');const j=D.ccri;
  if(!j)return '<section class="box gv"><div class="gv-head"><h2>CCRI, Made Simple</h2><p>Loading…</p></div></section>';
  const d=today(),dates=(j.dates||[]).filter(x=>(x.end||x.date)>=d),ev=(j.events||[]).filter(x=>x.date>=d);
  return '<section class="box gv"><div class="gv-head"><h2>'+X(j.title||'CCRI, Made Simple')+'</h2><p>'+X(j.intro||'')+'</p>'+
   '<label class="gv-search"><span>Search</span><input type="search" id="gvQ" placeholder="Try: financial aid, Lincoln, password, withdraw" autocomplete="off"></label>'+
   '<div class="gv-jump">'+[['dates','Key dates'],['offices','Get help'],['campuses','Campuses'],['events','Events'],['links','Quick links']].map(([k,l])=>'<a href="#gv-'+k+'" data-gvj="'+k+'">'+X(l)+'</a>').join('')+'</div>'+
   (j.main&&j.main.phone?'<div class="gv-help"><span><b>CCRI main line</b> '+tel(j.main.phone)+'</span></div>':'')+'</div>'+
   sec('dates','Key dates',dates.length+(j.tier==='free'?'+':''),(j.tier==='free'?regBox('The full CCRI calendar: every registration, add/drop, withdrawal, finals and holiday date through commencement.'):'')+dates.map(x=>'<div class="gv-row" data-q="'+X(x.what.toLowerCase())+'">'+dbox(x.date)+'<div class="gv-body"><b>'+X(x.what)+'</b><span class="gv-who">'+X(LONG(x.date))+(x.end&&x.end!==x.date?' – '+X(LONG(x.end)):'')+'</span></div></div>').join(''),true)+
   sec('offices','Get help',(j.offices||[]).length,(j.tier==='free'?regBox('Direct phone numbers, emails and hours for every CCRI office.'):'')+(j.offices||[]).map(o=>'<div class="gv-row" data-q="'+X((o.name+' '+(o.does||'')).toLowerCase())+'"><div class="gv-body"><b>'+X(o.name)+'</b>'+(o.does?'<p>'+X(o.does)+'</p>':'')+'<span class="gv-facts">'+fact('Phone',tel(o.phone))+fact('Email',o.email?'<a href="mailto:'+X(o.email)+'">'+X(o.email)+'</a>':'')+fact('Hours',X(o.hours))+'</span>'+(j.tier==='free'?'':ext(o.url))+'</div></div>').join(''))+
   sec('campuses','Campuses',(j.campuses||[]).length,(j.tier==='free'?'<p class="gv-memnote">🔓 Campus phone numbers: <button type="button" class="gv-regjoin gv-join-s">Free account</button></p>':'')+(j.campuses||[]).map(c=>'<div class="gv-row" data-q="'+X((c.name+' '+c.town).toLowerCase())+'"><div class="gv-body"><b>'+X(c.name)+' <small>'+X(c.town)+'</small></b>'+(c.notes?'<p>'+X(c.notes)+'</p>':'')+'<span class="gv-facts">'+fact('Phone',tel(c.phone))+fact('Address',X(c.address))+'</span>'+ext(c.map,'Campus page')+'</div></div>').join(''))+
   (ev.length?sec('events','Events',ev.length,ev.map(e=>'<div class="gv-row" data-q="'+X((e.title+' '+(e.campus||'')).toLowerCase())+'">'+dbox(e.date)+'<div class="gv-body"><b>'+X(e.title)+'</b><span class="gv-who">'+X(e.campus||'')+(e.time?' · '+X(e.time):'')+'</span>'+(e.note?'<p>'+X(e.note)+'</p>':'')+ext(e.url,'Details')+'</div></div>').join('')):'')+
   sec('links','Quick links',(j.links||[]).length,'<div class="gv-grid">'+(j.links||[]).map(l=>'<a class="gv-tile" data-q="'+X((l.label+' '+(l.why||'')).toLowerCase())+'" href="'+X(l.url)+'" target="_blank" rel="noopener"><b>'+X(l.label)+' ›</b><span>'+X(l.why||'')+'</span></a>').join('')+'</div>')+
   '<p class="gv-none" id="gvNone" hidden>Nothing matches. Try a shorter word, or call CCRI’s main line.</p>'+indep(j,'the Community College of Rhode Island')+'</section>'};

 /* search + jump links */
 document.addEventListener('input',e=>{if(e.target.id!=='gvQ')return;const q=e.target.value.trim().toLowerCase(),root=e.target.closest('.gv');let hits=0;
  const all=[...root.querySelectorAll('[data-q]')];all.forEach(r=>{r.hidden=!!q&&!r.dataset.q.includes(q)});
  if(q)all.forEach(r=>{if(r.dataset.q.includes(q))r.querySelectorAll('[data-q]').forEach(c=>c.hidden=false)});
  if(q)all.forEach(r=>{if(r.hidden)return;hits++;let p=r.parentElement;while(p&&p!==root){if(p.hasAttribute('data-q'))p.hidden=false;if(p.tagName==='DETAILS')p.open=true;p=p.parentElement}});
  root.querySelectorAll('.gv-band,.gv-sec,.gv-branch,.gv-comm,.gv-sd').forEach(s=>{if(!q){s.hidden=false;return}s.hidden=![...s.querySelectorAll('[data-q]')].some(r=>!r.hidden)});
  if(!q)root.querySelectorAll('details[open]').forEach(d=>{if(!d.matches('.gv-sec'))d.open=false});
  const no=root.querySelector('#gvNone');if(no)no.hidden=!q||hits>0});
 document.addEventListener('click',e=>{const a=e.target.closest('[data-gvj]');if(!a)return;e.preventDefault();const s=document.getElementById('gv-'+a.dataset.gvj);if(s){s.open=true;s.scrollIntoView({behavior:'smooth',block:'start'})}});

